-- 4) 核对
SELECT 'children' AS tbl, count(*) FROM children
UNION ALL SELECT 'enrollments', count(*) FROM enrollments
UNION ALL SELECT 'attendance', count(*) FROM attendance
UNION ALL SELECT 'teachers', count(*) FROM teachers
UNION ALL SELECT 'classes', count(*) FROM classes;

SELECT 'att_course_filled' AS chk, count(*) FROM attendance WHERE course_type IS NOT NULL AND course_type <> '';
SELECT 'enroll_end_filled' AS chk, count(*) FROM enrollments WHERE end_date IS NOT NULL;
SELECT 'children_active' AS chk, count(*) FROM children WHERE status = 'active';
SELECT 'att_course_missing' AS chk, count(*) FROM attendance WHERE course_type IS NULL OR course_type = '';
SELECT 'enroll_end_missing' AS chk, count(*) FROM enrollments WHERE end_date IS NULL;

COMMIT;